 async function changeOwnPassword(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;setPasswordError('');if(newPassword.length<12){setPasswordError('New password must be at least 12 characters.');return}if(newPassword!==confirmPassword){setPasswordError('New passwords do not match.');return}if(currentPassword===newPassword){setPasswordError('Choose a different password.');return}setPasswordSaving(true);try{const {data:{user:authUser},error:userError}=await supabase.auth.getUser();if(userError||!authUser?.email)throw new Error('Please sign in again.');const {error:verifyError}=await supabase.auth.signInWithPassword({email:authUser.email,password:currentPassword});if(verifyError)throw new Error('Current password is incorrect.');const {error:updateError}=await supabase.auth.updateUser({password:newPassword});if(updateError)throw updateError;if(forcePasswordChange)await backend.completeFirstLogin();setForcePasswordChange(false);setChangePasswordOpen(false);setCurrentPassword('');setNewPassword('');setConfirmPassword('');notify('Password changed successfully.','success')}catch(e:any){setPasswordError(e.message||'Unable to change password.')}finally{setPasswordSaving(false)}}
