 useEffect(()=>{if(!signedIn||role!=='Cashier'||!supabase||requiredCashTask)return;let active=true;async function checkReminder(){const clock=phMinutes();if(clock<1010||clock>=1020)return;const key=`closing-task-reminder:${businessDay()}`;try{const next=Number(localStorage.getItem(key)||0);if(next&&Date.now()<next)return}catch{}const {data:{user:authUser}}=await supabase!.auth.getUser();if(!authUser)return;const {data:profile}=await supabase!.from('profiles').select('branch_id').eq('id',authUser.id).maybeSingle();if(!profile?.branch_id)return;const [{data:counts},{data:turnover}]=await Promise.all([supabase!.from('daily_cash_counts').select('cash_account,count_type').eq('branch_id',profile.branch_id).eq('business_date',businessDay()),supabase!.from('daily_sales_handovers').select('id').eq('branch_id',profile.branch_id).eq('business_date',businessDay()).limit(1)]);const missing:('Sales Turnover'|'Petty Cash')[]=[];if(!(counts||[]).some(x=>x.cash_account==='Petty Cash'&&x.count_type==='EOD'))missing.push('Petty Cash');if(!(turnover||[]).length)missing.push('Sales Turnover');if(active&&missing.length){setClosingReminder(missing);notify('Closing tasks required soon. Complete the Revolving Fund Closing Cash Count and Sales Turnover before 5:00 PM.','warning');try{localStorage.setItem(key,String(Date.now()+5*60*1000))}catch{}}}void checkReminder();const timer=setInterval(()=>void checkReminder(),30000);return()=>{active=false;clearInterval(timer)}},[signedIn,role,notify,requiredCashTask]);
 function record(capturedProof?:string){const account=screen==='Funds'?'Funds':'Petty Cash';const rfpExpense=account==='Funds'&&draft.kind==='Expense';const qty=Number(draft.quantity||1),unitCost=Number(draft.unitCost||0);const amount=rfpExpense?qty*unitCost:Number(draft.amount);const expenseMissing=draft.kind==='Expense'&&(!draft.payee.trim()||!draft.vatType);const rfpMissing=rfpExpense&&(!draft.branchId||!['Part','Supply'].includes(draft.category)||!draft.vehicleUnit.trim()||!draft.plateNumber.trim()||!Number.isFinite(qty)||qty<=0||!Number.isFinite(unitCost)||unitCost<=0);if(!Number.isFinite(amount)||amount<=0||!draft.category.trim()||!draft.description.trim()||!draft.transactionDate||expenseMissing||rfpMissing||!signature||(draft.kind==='Additional Funds'&&!capturedProof)){notify(rfpExpense?'Complete the Part/Supply details, branch, unit/plate and signature.':'Complete the required transaction details, signature and proof.','error');return}void action(async()=>{const prefix=account==='Funds'?(draft.kind==='Expense'?'RFP-EXP':'RFP-REP'):(draft.kind==='Expense'?'RF-EXP':'RF-REP');const id=await backend.nextTransactionNumber(prefix);if(account==='Petty Cash')await backend.addExpenseCategory(account,draft.category);const entry:LedgerEntry={id,account,kind:draft.kind,amount,category:draft.category.trim(),description:draft.description.trim(),actor:user,createdAt:now(),transactionDate:draft.transactionDate,payee:draft.payee.trim(),vatType:draft.vatType,cashVoucherNo:draft.cashVoucherNo.trim(),receiptNo:draft.receiptNo.trim(),tinNo:draft.tinNo.trim(),notes:draft.notes.trim(),vehicleUnit:draft.vehicleUnit.trim(),plateNumber:normalizePlate(draft.plateNumber),quantity:rfpExpense?qty:1,unitCost:rfpExpense?unitCost:amount,branchId:rfpExpense?draft.branchId:'',signature,proof:capturedProof,status:'Pending for Approval',events:[]};await backend.createCash(entry);setModal(null);setSignature('');setCameraProof('');setDraft(initialDraft());setSelected(id)})}
