 function addPayment(){const a=Number(posDraft.payment),reference=posDraft.paymentReference.trim(),fee=Number(posDraft.terminalFee||0),cardType=posDraft.cardType.trim();if(!(a>0)||a>posTotal-posPaid){notify('Enter a positive amount within the outstanding balance.','warning');return}if(posDraft.method!=='Cash'&&!reference){notify('Payment reference is required for non-cash payments.','warning');return}if(posDraft.method==='Card'&&!cardType){notify('Card Type is required for card payments.','warning');return}if(!Number.isFinite(fee)||fee<0||fee>a){notify('Enter a valid terminal fee.','warning');return}if(!window.confirm(`Confirm payment: ${peso(a)} — ${pesoInWords(a)}\nMethod: ${posDraft.method}${cardType?`\nCard: ${cardType}`:''}${reference?`\nReference: ${reference}`:''}${fee?`\nTerminal Fee: ${peso(fee)}`:''}`))return;setPosPayments(p=>[...p,{amount:a,method:posDraft.method,reference,cardType:posDraft.method==='Card'?cardType:undefined,terminalFee:posDraft.method==='Card'?fee:0,at:now()}]);setPosDraft(p=>({...p,payment:'',paymentReference:'',cardType:'',terminalFee:'0'}))}
 function submitPos(){const vehicle=[posVehicle.year,posVehicle.brand,posVehicle.model].filter(Boolean).join(' ').trim();if(!posDraft.client.trim()||!vehicle||!posItems.length||posPayments.length===0||posItems.some(i=>!['Service','Part'].includes(i.type)||!i.name.trim()||!Number.isFinite(i.price)||i.price<0||!Number.isFinite(i.qty)||i.qty<=0)||posCosts.some(i=>i.name.trim()&&(!i.supplier.trim()||!Number.isFinite(i.unitCost)||i.unitCost<0||!Number.isFinite(i.qty)||i.qty<=0))){notify('Complete the client, vehicle details, quotation, required payment and valid itemized costs.','warning');return}if(!window.confirm(`Submit POS as Pending?\nQuotation: ${peso(posTotal)} — ${pesoInWords(posTotal)}\nClient: ${posDraft.client}\nVehicle: ${vehicle}`))return;void action(async()=>{const id=await backend.nextTransactionNumber('POS');const p:PosEntry={id,client:posDraft.client,phone:posDraft.phone,vehicle,vehicleYear:posVehicle.year||undefined,vehicleBrand:posVehicle.brand||undefined,vehicleModel:posVehicle.model||undefined,plate:normalizePlate(posDraft.plate),concern:posDraft.concern,items:posItems,payments:posPayments,costs:cogsTotal,cogsItems:posCosts.filter(x=>x.name.trim()),status:'Pending',createdAt:now(),bsSi:posDraft.bsSi,customerTin:posDraft.customerTin,address:posDraft.address,mileage:posDraft.mileage,platform:posDraft.platform,serviceAdvisor:posDraft.serviceAdvisor,bookedBy:posDraft.bookedBy,mechanic:posDraft.mechanic,remarks:posDraft.remarks,onlineExpense:Number(posDraft.onlineExpense||0),rfExpense:Number(posDraft.rfExpense||0)};await backend.createPos(p);resetPos()})}
 function submitAdditional(){const p=data.pos.find(x=>x.id===additionalPos);if(!p||p.status!=='Pending')return;const quotation=addItems.filter(x=>x.name.trim()&&x.qty>0&&x.price>=0);const cogs=addCosts.filter(x=>x.name.trim()&&x.qty>0&&x.unitCost>=0);if(!quotation.length||addItems.some(x=>x.name.trim()&&(!['Service','Part'].includes(x.type)||!Number.isFinite(x.price)||x.price<0||x.qty<=0))||addCosts.some(x=>x.name.trim()&&(!Number.isFinite(x.unitCost)||x.unitCost<0||x.qty<=0))){notify('Complete the additional items and valid costs.','error');return}const amount=quotation.reduce((n,x)=>n+x.qty*x.price,0);if(!window.confirm(`Confirm additional transaction: ${peso(amount)} — ${pesoInWords(amount)}?`))return;void action(async()=>{await backend.addPosAdditional(p.id,quotation,cogs);setAdditionalPos(null);setAddItems([{type:'Service',name:'',qty:1,price:0}]);setAddCosts([{name:'',supplier:'',qty:1,unitCost:0}])})}
 function payPending(){const p=data.pos.find(x=>x.id===paymentPos);if(!p)return;const due=p.items.reduce((v,x)=>v+x.price*x.qty,0)-p.payments.reduce((v,x)=>v+x.amount,0);const amount=Number(extraPayment),reference=extraReference.trim(),fee=Number(extraTerminalFee||0),cardType=extraCardType.trim();if(!Number.isFinite(amount)||amount<=0||amount>due){notify('Enter a valid amount up to the remaining balance.','warning');return}if(extraMethod!=='Cash'&&!reference){notify('Payment reference is required for non-cash payments.','warning');return}if(extraMethod==='Card'&&!cardType){notify('Card Type is required.','warning');return}if(fee<0||fee>amount){notify('Enter a valid terminal fee.','warning');return}if(!window.confirm(`Confirm additional payment: ${peso(amount)} — ${pesoInWords(amount)}\nMethod: ${extraMethod}${cardType?`\nCard: ${cardType}`:''}${reference?`\nReference: ${reference}`:''}`))return;void action(async()=>{await backend.addPosPayment(p.id,amount,extraMethod,reference,cardType,fee);setPaymentPos(null);setExtraPayment('');setExtraReference('');setExtraCardType('');setExtraTerminalFee('0')})}
 function finalizePos(id:string){const entry=data.pos.find(p=>p.id===id);if(!entry||entry.status!=='Pending')return;const due=entry.items.reduce((sum,i)=>sum+i.qty*i.price,0),paid=entry.payments.reduce((sum,p)=>sum+p.amount,0);if(Math.abs(due-paid)>0.005){notify('Account must be fully paid.');return}if(!window.confirm('Close this POS account?'))return;void action(()=>backend.closePos(id))}
