 const plateSuggestions=useMemo(()=>{const q=normalizePlate(posDraft.plate);if(!q)return [] as PosEntry[];const ordered=[...data.pos].sort((a,b)=>new Date(b.closedAt||b.createdAt).getTime()-new Date(a.closedAt||a.createdAt).getTime());const seen=new Set<string>();return ordered.filter(row=>{const key=normalizePlate(row.plate);if(!key||!key.includes(q)||seen.has(key))return false;seen.add(key);return true}).slice(0,7)},[data.pos,posDraft.plate]);
